def ensure_table_exists(self):
    if not self.conn.execute(
        """
        SELECT name
        FROM sqlite_master
        WHERE type='table'
        AND name=?
    """,
        (self.table_name,),
    ).fetchall():
        create_sql = """
            CREATE TABLE "{table_name}" (
                "id" INTEGER PRIMARY KEY,
                "{value_column}" TEXT
            );
        """.format(
            table_name=self.table_name, value_column=self.value_column
        )
        self.conn.execute(create_sql)
        if self.index_fts:
            # Add a FTS index on the value_column
            self.conn.execute(
                """
                CREATE VIRTUAL TABLE "{fts_table_name}"
                USING {fts_version} ({value_column}, content="{table_name}");
            """.format(
                    fts_version=best_fts_version(),
                    fts_table_name=self.fts_table_name,
                    table_name=self.table_name,
                    value_column=self.value_column,
                )
            )

def get_create_table_sql(
    table_name, df, index=True, sql_type_overrides=None, primary_keys=None
):
    # Create a temporary table with just the first row
    # We do this in memory because we just want to get the
    # CREATE TABLE statement
    # Returns (sql, columns)
    conn = sqlite3.connect(":memory:")
    # Before calling to_sql we need correct the dtypes that we will be using
    # to pick the right SQL column types. pandas mostly gets this right...
    # except for columns that contain a mixture of integers and Nones. These
    # will be incorrectly detected as being of DB type REAL when we want them
    # to be INTEGER instead.
    # http://pandas.pydata.org/pandas-docs/stable/gotchas.html#support-for-integer-na
    sql_type_overrides = sql_type_overrides or {}
    if isinstance(df, pd.DataFrame):
        columns_and_types = df.dtypes.iteritems()
    elif isinstance(df, pd.Series):
        columns_and_types = [(df.name, df.dtype)]
    for column, dtype in columns_and_types:
        # Are any of these float columns?
        if dtype in (np.float32, np.float64):
            # if every non-NaN value is an integer, switch to int
            if isinstance(df, pd.Series):
                series = df
            else:
                series = df[column]
            num_non_integer_floats = series.map(
                lambda v: not np.isnan(v) and not v.is_integer()
            ).sum()
            if num_non_integer_floats == 0:
                # Everything was NaN or an integer-float - switch type:
                sql_type_overrides[column] = "INTEGER"

    df[:1].to_sql(table_name, conn, index=index, dtype=sql_type_overrides)
    sql = conn.execute(
        "select sql from sqlite_master where name = ?", [table_name]
    ).fetchone()[0]
    columns = [
        row[1] for row in conn.execute("PRAGMA table_info([{}])".format(table_name))
    ]
    if primary_keys:
        # Rewrite SQL to add PRIMARY KEY (col1, col2) at end
        assert sql[-1] == ")"
        sql = sql[:-1] + "  ,PRIMARY KEY ({cols})\n)".format(
            cols=", ".join("[{}]".format(col) for col in primary_keys)
        )
    return sql, columns

def __repr__(self):
    return "<{}: {} rows>".format(
        self.table_name,
        self.conn.execute(
            'select count(*) from "{}"'.format(self.table_name)
        ).fetchone()[0],
    )

def id_for_value(self, value):
    if pd.isnull(value):
        return None
    # value should be a string
    if not isinstance(value, six.string_types):
        if isinstance(value, float):
            value = "{0:g}".format(value)
        else:
            value = six.text_type(value)
    try:
        # First try our in-memory cache
        return self.cache[value]
    except KeyError:
        # Next try the database table
        sql = 'SELECT id FROM "{table_name}" WHERE "{value_column}"=?'.format(
            table_name=self.table_name, value_column=self.value_column
        )
        result = self.conn.execute(sql, (value,)).fetchall()
        if result:
            id = result[0][0]
        else:
            # Not in DB! Insert it
            cursor = self.conn.cursor()
            cursor.execute(
                """
                INSERT INTO "{table_name}" ("{value_column}") VALUES (?);
            """.format(
                    table_name=self.table_name, value_column=self.value_column
                ),
                (value,),
            )
            id = cursor.lastrowid
            if self.index_fts:
                # And update FTS index
                sql = """
                    INSERT INTO "{fts_table_name}" (rowid, "{value_column}") VALUES (?, ?);
                """.format(
                    fts_table_name=self.fts_table_name,
                    value_column=self.value_column,
                )
                cursor.execute(sql, (id, value))

        self.cache[value] = id
        return id

def cli(
    paths,
    dbname,
    separator,
    quoting,
    skip_errors,
    replace_tables,
    table,
    extract_column,
    date,
    datetime,
    datetime_format,
    primary_key,
    fts,
    index,
    shape,
    filename_column,
    fixed_columns,
    fixed_columns_int,
    fixed_columns_float,
    no_index_fks,
    no_fulltext_fks,
    just_strings,
):
    """
    PATHS: paths to individual .csv files or to directories containing .csvs

    DBNAME: name of the SQLite database file to create
    """
    # make plural for more readable code:
    extract_columns = extract_column
    del extract_column

    if extract_columns:
        click.echo("extract_columns={}".format(extract_columns))
    if dbname.endswith(".csv"):
        raise click.BadParameter("dbname must not end with .csv")
    if "." not in dbname:
        dbname += ".db"

    db_existed = os.path.exists(dbname)

    conn = sqlite3.connect(dbname)

    dataframes = []
    csvs = csvs_from_paths(paths)
    sql_type_overrides = None
    for name, path in csvs.items():
        try:
            df = load_csv(
                path, separator, skip_errors, quoting, shape, just_strings=just_strings
            )
            df.table_name = table or name
            if filename_column:
                df[filename_column] = name
                if shape:
                    shape += ",{}".format(filename_column)
            if fixed_columns:
                for colname, value in fixed_columns:
                    df[colname] = value
                    if shape:
                        shape += ",{}".format(colname)
            if fixed_columns_int:
                for colname, value in fixed_columns_int:
                    df[colname] = value
                    if shape:
                        shape += ",{}".format(colname)
            if fixed_columns_float:
                for colname, value in fixed_columns_float:
                    df[colname] = value
                    if shape:
                        shape += ",{}".format(colname)
            sql_type_overrides = apply_shape(df, shape)
            apply_dates_and_datetimes(df, date, datetime, datetime_format)
            dataframes.append(df)
        except LoadCsvError as e:
            click.echo("Could not load {}: {}".format(path, e), err=True)

    click.echo("Loaded {} dataframes".format(len(dataframes)))

    # Use extract_columns to build a column:(table,label) dictionary
    foreign_keys = {}
    for col in extract_columns:
        bits = col.split(":")
        if len(bits) == 3:
            foreign_keys[bits[0]] = (bits[1], bits[2])
        elif len(bits) == 2:
            foreign_keys[bits[0]] = (bits[1], "value")
        else:
            foreign_keys[bits[0]] = (bits[0], "value")

    # Now we have loaded the dataframes, we can refactor them
    created_tables = {}
    refactored = refactor_dataframes(
        conn, dataframes, foreign_keys, not no_fulltext_fks
    )
    for df in refactored:
        # This is a bit trickier because we need to
        # create the table with extra SQL for foreign keys
        if replace_tables and table_exists(conn, df.table_name):
            drop_table(conn, df.table_name)
        if table_exists(conn, df.table_name):
            df.to_sql(df.table_name, conn, if_exists="append", index=False)
        else:
            to_sql_with_foreign_keys(
                conn,
                df,
                df.table_name,
                foreign_keys,
                sql_type_overrides,
                primary_keys=primary_key,
                index_fks=not no_index_fks,
            )
            created_tables[df.table_name] = df
        if index:
            for index_defn in index:
                add_index(conn, df.table_name, index_defn)

    # Create FTS tables
    if fts:
        fts_version = best_fts_version()
        if not fts_version:
            conn.close()
            raise click.BadParameter(
                "Your SQLite version does not support any variant of FTS"
            )
        # Check that columns make sense
        for table, df in created_tables.items():
            for fts_column in fts:
                if fts_column not in df.columns:
                    raise click.BadParameter(
                        'FTS column "{}" does not exist'.format(fts_column)
                    )

        generate_and_populate_fts(conn, created_tables.keys(), fts, foreign_keys)

    conn.close()

    if db_existed:
        click.echo(
            "Added {} CSV file{} to {}".format(
                len(csvs), "" if len(csvs) == 1 else "s", dbname
            )
        )
    else:
        click.echo(
            "Created {} from {} CSV file{}".format(
                dbname, len(csvs), "" if len(csvs) == 1 else "s"
            )
        )
